-- Baseline foundation schema — reconstructed, not original.
--
-- Context: the live pilu-ai.app Supabase project (ref kcgtcitpxzmkeddaxdku)
-- has 17 applied migrations. Only the 12 most recent (Sleep Sounds onward,
-- 2026-07-31) were ever committed as files in this repo. The 5 earliest —
-- initial_pilu_foundation, add_timeline_events, add_feature_data_details,
-- harden_function_permissions, add_emergency_contacts (all 2026-07-30) —
-- were applied directly to the live project and never saved. This file
-- closes that gap.
--
-- It was generated by introspecting the LIVE schema via the Supabase MCP
-- SQL channel (pg_catalog/information_schema/pg_policies), not written
-- from memory, and captures every table/enum/function/policy/index/trigger
-- that isn't already accounted for by the 12 existing migration files in
-- this directory. Applying this file plus the existing 12, in order,
-- against an empty Supabase project reproduces the current live schema.
--
-- This file has NOT been applied to the live project (it's already live —
-- applying it there would fail on "already exists"). It exists so this
-- repo can stand up a second environment or recover from scratch. See
-- DEPLOYMENT.md §3 and RELEASE_CHECKLIST.md §3 for the full context.
--
-- Sequencing note: four columns that exist on the live tables today are
-- deliberately NOT created here, because the 12 existing migration files
-- add them later in sequence and would fail on "column already exists"
-- otherwise: profiles.subscription_tier (+ its CHECK) and
-- profiles.analytics_consent, family_members.last_seen_at, and
-- babies.mother_name/father_name. Every CREATE TABLE/TYPE/INDEX/POLICY
-- name in this file was cross-checked against all 12 existing migration
-- files for collisions. This file was not test-applied against a live or
-- local Postgres instance — this sandbox has no Postgres and no network
-- path to Supabase's API — so review it before relying on it in a real
-- disaster-recovery scenario.

create extension if not exists pgcrypto with schema extensions;

-- ── Enum types ────────────────────────────────────────────────────────────

create type public.family_role as enum ('owner', 'parent', 'caregiver');
create type public.family_member_status as enum ('invited', 'active', 'removed');
create type public.feeding_type as enum ('breastfeeding', 'bottle', 'formula', 'pumped_milk', 'solid_food', 'water', 'custom');
create type public.sleep_type as enum ('nap', 'night_sleep', 'custom');
create type public.vaccine_status as enum ('scheduled', 'completed', 'postponed', 'skipped');
create type public.ai_message_role as enum ('user', 'assistant', 'system');
create type public.emergency_contact_type as enum ('general_emergency', 'pediatrician', 'clinic', 'trusted_caregiver', 'poison_information');

-- ── Shared trigger function ─────────────────────────────────────────────

create or replace function public.set_updated_at()
returns trigger
language plpgsql
set search_path to 'public'
as $function$ begin new.updated_at = now(); return new; end; $function$;

-- ── Tables ───────────────────────────────────────────────────────────────

-- NOTE: subscription_tier (+ its CHECK) and analytics_consent are added
-- later by 20260731080845_add_sleep_sounds.sql and
-- 20260731150000_add_analytics_consent.sql respectively — omitted here so
-- those ALTER TABLE statements have something to add rather than
-- colliding with a column that already exists.
create table public.profiles (
  id uuid not null,
  display_name text,
  first_name text,
  last_name text,
  avatar_url text,
  preferred_language text not null default 'en'::text,
  timezone text not null default 'UTC'::text,
  onboarding_completed boolean not null default false,
  created_at timestamp with time zone not null default now(),
  updated_at timestamp with time zone not null default now(),
  constraint profiles_pkey primary key (id),
  constraint profiles_id_fkey foreign key (id) references auth.users(id) on delete cascade,
  constraint profiles_preferred_language_check check (char_length(preferred_language) >= 2 and char_length(preferred_language) <= 16)
);

create table public.families (
  id uuid not null default gen_random_uuid(),
  name text not null,
  owner_id uuid not null,
  invite_code text not null default substr(replace((gen_random_uuid())::text, '-', ''), 1, 16),
  created_at timestamp with time zone not null default now(),
  updated_at timestamp with time zone not null default now(),
  constraint families_pkey primary key (id),
  constraint families_owner_id_fkey foreign key (owner_id) references public.profiles(id) on delete restrict,
  constraint families_invite_code_key unique (invite_code),
  constraint families_invite_code_check check (char_length(invite_code) >= 12),
  constraint families_name_check check (char_length(trim(name)) >= 1 and char_length(trim(name)) <= 120)
);

-- NOTE: last_seen_at is added later by
-- 20260731090426_add_family_collaboration.sql — omitted here for the same
-- reason as profiles.subscription_tier above.
create table public.family_members (
  id uuid not null default gen_random_uuid(),
  family_id uuid not null,
  user_id uuid not null,
  role public.family_role not null default 'parent'::public.family_role,
  status public.family_member_status not null default 'invited'::public.family_member_status,
  joined_at timestamp with time zone,
  created_at timestamp with time zone not null default now(),
  constraint family_members_pkey primary key (id),
  constraint family_members_family_id_fkey foreign key (family_id) references public.families(id) on delete cascade,
  constraint family_members_user_id_fkey foreign key (user_id) references public.profiles(id) on delete cascade,
  constraint family_members_family_id_user_id_key unique (family_id, user_id)
);

-- NOTE: mother_name and father_name are added later by
-- 20260731140313_add_baby_parent_names.sql — omitted here for the same
-- reason as profiles.subscription_tier above.
create table public.babies (
  id uuid not null default gen_random_uuid(),
  family_id uuid not null,
  first_name text not null,
  last_name text,
  nickname text,
  date_of_birth date,
  due_date date,
  biological_sex text,
  birth_weight_grams numeric(8,2),
  birth_length_cm numeric(6,2),
  avatar_url text,
  notes text,
  is_active boolean not null default true,
  created_at timestamp with time zone not null default now(),
  updated_at timestamp with time zone not null default now(),
  constraint babies_pkey primary key (id),
  constraint babies_family_id_fkey foreign key (family_id) references public.families(id) on delete cascade,
  constraint babies_first_name_check check (char_length(trim(first_name)) >= 1 and char_length(trim(first_name)) <= 80),
  constraint babies_biological_sex_check check (biological_sex = any (array['female'::text, 'male'::text, 'intersex'::text, 'not_specified'::text])),
  constraint babies_birth_weight_grams_check check (birth_weight_grams is null or birth_weight_grams >= 0),
  constraint babies_birth_length_cm_check check (birth_length_cm is null or birth_length_cm >= 0),
  constraint babies_check check (date_of_birth is null or due_date is null or due_date <= date_of_birth)
);

create table public.feeding_logs (
  id uuid not null default gen_random_uuid(),
  baby_id uuid not null,
  created_by uuid,
  feeding_type public.feeding_type not null,
  started_at timestamp with time zone not null,
  ended_at timestamp with time zone,
  duration_minutes integer,
  breast_side text,
  amount_ml numeric(8,2),
  food_name text,
  notes text,
  created_at timestamp with time zone not null default now(),
  updated_at timestamp with time zone not null default now(),
  constraint feeding_logs_pkey primary key (id),
  constraint feeding_logs_baby_id_fkey foreign key (baby_id) references public.babies(id) on delete cascade,
  constraint feeding_logs_created_by_fkey foreign key (created_by) references public.profiles(id) on delete set null,
  constraint feeding_logs_breast_side_check check (breast_side is null or breast_side = any (array['left'::text, 'right'::text, 'both'::text])),
  constraint feeding_logs_amount_ml_check check (amount_ml is null or amount_ml >= 0),
  constraint feeding_logs_duration_minutes_check check (duration_minutes is null or duration_minutes >= 0),
  constraint feeding_logs_check check (ended_at is null or ended_at >= started_at)
);

create table public.sleep_logs (
