-- ── Indexes ──────────────────────────────────────────────────────────────

create index babies_family_active_idx on public.babies using btree (family_id, is_active);
create index family_members_family_user_active_idx on public.family_members using btree (family_id, user_id) where (status = 'active'::public.family_member_status);
create index feeding_logs_baby_started_idx on public.feeding_logs using btree (baby_id, started_at desc);
create index sleep_logs_baby_started_idx on public.sleep_logs using btree (baby_id, started_at desc);
create index diaper_logs_baby_logged_idx on public.diaper_logs using btree (baby_id, logged_at desc);
create index growth_logs_baby_measured_idx on public.growth_logs using btree (baby_id, measured_at desc);
create index milestones_baby_achieved_idx on public.milestones using btree (baby_id, achieved_at desc);
create index vaccines_baby_scheduled_idx on public.vaccines using btree (baby_id, scheduled_date);
create index medicine_logs_baby_administered_idx on public.medicine_logs using btree (baby_id, administered_at desc);
create index medicine_plans_baby_active_idx on public.medicine_plans using btree (baby_id, active);
create index memories_baby_occurred_idx on public.memories using btree (baby_id, occurred_at desc);
create index journal_entries_baby_date_idx on public.journal_entries using btree (baby_id, entry_date desc);
create index ai_conversations_user_updated_idx on public.ai_conversations using btree (user_id, updated_at desc);
create index ai_messages_conversation_created_idx on public.ai_messages using btree (conversation_id, created_at);
create index timeline_events_baby_occurred_idx on public.timeline_events using btree (baby_id, occurred_at desc);
create index emergency_contacts_family_idx on public.emergency_contacts using btree (family_id);

-- ── Access-check functions (SECURITY DEFINER, RPC layer) ───────────────
-- Each does its own authorization check internally; EXECUTE is revoked
-- from anon/public below, matching the pattern the later migrations in
-- this directory use and harden further.

create or replace function public.is_active_family_member(target_family_id uuid)
returns boolean
language sql
stable security definer
set search_path to 'public'
as $function$
  select exists (select 1 from public.family_members fm where fm.family_id = target_family_id and fm.user_id = (select auth.uid()) and fm.status = 'active');
$function$;

create or replace function public.is_family_owner(target_family_id uuid)
returns boolean
language sql
stable security definer
set search_path to 'public'
as $function$
  select exists (select 1 from public.families f where f.id = target_family_id and f.owner_id = (select auth.uid()));
$function$;

create or replace function public.can_access_baby(target_baby_id uuid)
returns boolean
language sql
stable security definer
set search_path to 'public'
as $function$
  select exists (select 1 from public.babies b where b.id = target_baby_id and public.is_active_family_member(b.family_id));
$function$;

create or replace function public.owns_ai_conversation(target_conversation_id uuid)
returns boolean
language sql
stable security definer
set search_path to 'public'
as $function$
  select exists (select 1 from public.ai_conversations c where c.id = target_conversation_id and c.user_id = (select auth.uid()));
$function$;

create or replace function public.create_family(family_name text)
returns uuid
language plpgsql
security definer
set search_path to 'public'
as $function$
declare new_family_id uuid;
begin
  if (select auth.uid()) is null then raise exception 'Authentication is required'; end if;
  if nullif(trim(family_name), '') is null then raise exception 'Family name is required'; end if;
  insert into public.families (name, owner_id) values (trim(family_name), (select auth.uid())) returning id into new_family_id;
  insert into public.family_members (family_id, user_id, role, status, joined_at) values (new_family_id, (select auth.uid()), 'owner', 'active', now());
  return new_family_id;
end; $function$;

revoke execute on function public.is_active_family_member(uuid) from public;
revoke execute on function public.is_active_family_member(uuid) from anon;
grant execute on function public.is_active_family_member(uuid) to authenticated;

revoke execute on function public.is_family_owner(uuid) from public;
revoke execute on function public.is_family_owner(uuid) from anon;
grant execute on function public.is_family_owner(uuid) to authenticated;

revoke execute on function public.can_access_baby(uuid) from public;
revoke execute on function public.can_access_baby(uuid) from anon;
grant execute on function public.can_access_baby(uuid) to authenticated;

revoke execute on function public.owns_ai_conversation(uuid) from public;
revoke execute on function public.owns_ai_conversation(uuid) from anon;
grant execute on function public.owns_ai_conversation(uuid) to authenticated;

revoke execute on function public.create_family(text) from public;
revoke execute on function public.create_family(text) from anon;
grant execute on function public.create_family(text) to authenticated;

-- ── New-user provisioning (auth.users -> public.profiles) ──────────────

create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $function$ begin
  insert into public.profiles (id, display_name, first_name, avatar_url)
  values (new.id, nullif(new.raw_user_meta_data ->> 'full_name', ''), nullif(coalesce(new.raw_user_meta_data ->> 'first_name', split_part(coalesce(new.raw_user_meta_data ->> 'full_name', ''), ' ', 1)), ''), nullif(new.raw_user_meta_data ->> 'avatar_url', ''))
  on conflict (id) do nothing;
  return new;
end; $function$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- ── Row Level Security ───────────────────────────────────────────────────

alter table public.profiles enable row level security;
alter table public.families enable row level security;
alter table public.family_members enable row level security;
alter table public.babies enable row level security;
alter table public.feeding_logs enable row level security;
alter table public.sleep_logs enable row level security;
alter table public.diaper_logs enable row level security;
alter table public.growth_logs enable row level security;
alter table public.milestones enable row level security;
alter table public.vaccines enable row level security;
alter table public.medicine_logs enable row level security;
alter table public.medicine_plans enable row level security;
alter table public.memories enable row level security;
alter table public.journal_entries enable row level security;
alter table public.article_bookmarks enable row level security;
alter table public.article_feedback enable row level security;
alter table public.ai_conversations enable row level security;
alter table public.ai_messages enable row level security;
alter table public.timeline_events enable row level security;
alter table public.emergency_contacts enable row level security;

-- profiles: each user owns exactly their own row
create policy profiles_select_own on public.profiles for select to authenticated using ((select auth.uid()) = id);
create policy profiles_insert_own on public.profiles for insert to authenticated with check ((select auth.uid()) = id);
create policy profiles_update_own on public.profiles for update to authenticated using ((select auth.uid()) = id) with check ((select auth.uid()) = id);

-- families
create policy families_select_members on public.families for select to authenticated using (public.is_active_family_member(id));
create policy families_update_owner on public.families for update to authenticated using (public.is_family_owner(id)) with check (owner_id = (select auth.uid()));
create policy families_delete_owner on public.families for delete to authenticated using (public.is_family_owner(id));

-- family_members
create policy family_members_select_members on public.family_members for select to authenticated using (public.is_active_family_member(family_id));
create policy family_members_insert_owner on public.family_members for insert to authenticated with check (public.is_family_owner(family_id));
create policy family_members_update_owner on public.family_members for update to authenticated using (public.is_family_owner(family_id)) with check (public.is_family_owner(family_id));
create policy family_members_delete_owner on public.family_members for delete to authenticated using (public.is_family_owner(family_id));

-- babies
create policy babies_select_members on public.babies for select to authenticated using (public.is_active_family_member(family_id));
create policy babies_insert_members on public.babies for insert to authenticated with check (public.is_active_family_member(family_id));
create policy babies_update_members on public.babies for update to authenticated using (public.is_active_family_member(family_id)) with check (public.is_active_family_member(family_id));
create policy babies_delete_members on public.babies for delete to authenticated using (public.is_active_family_member(family_id));

